mns['date'];unset($columns['date']);$columns['type']=esc_html__('Type','sina-ext');$columns['status']=esc_html__('Display','sina-ext');$columns['date']=esc_html($column_date);return $columns;}public function columns_content($column_name,$post_id){$type=get_post_meta($post_id,self::POST_TYPE_META.'_type',true);$template_type=self::get_template_type();if(!array_key_exists($type,$template_type)){return;}if($column_name==='type'){echo isset($template_type[$type])?'<div class="column-type">'.esc_html($template_type[$type]['label']).'</div>':'-';}if($column_name==='status'){$display=get_post_meta($post_id,self::POST_TYPE_META.'_location',true); ?>
            <div class="post-status">
                <strong><?php esc_html_e('Display:','sina-ext'); ?> </strong>
                <?php echo esc_html($display); ?>
            </div>
            <?php }}public function create_template($data){$args=['post_type'=>self::POST_TYPE,'post_status'=>'publish','post_title'=>$data['title'],];$new_post_id=wp_insert_post($args);if($new_post_id&&!is_wp_error($new_post_id)){update_post_meta($new_post_id,self::POST_TYPE_META.'_type',$data['tmptype']);update_post_meta($new_post_id,self::POST_TYPE_META.'_location',$data['tmplocation']);update_post_meta($new_post_id,'_elementor_edit_mode','builder');update_post_meta($new_post_id,'_wp_page_template','elementor_canvas');if(in_array($data['tmptype'],['header','footer','popup','sidebar'])){update_post_meta($new_post_id,self::POST_TYPE_META.'_splocation',$data['tmpSpLocation']);}if('popup'===$data['tmptype']){update_post_meta($new_post_id,'_elementor_template_type','sina_popup');}elseif('sidebar'===$data['tmptype']){update_post_meta($new_post_id,'_elementor_template_type','sina_sidebar');}wp_send_json_success(['message'=>esc_html__('Template has been inserted','sina-ext'),'id'=>$new_post_id,]);}else{wp_send_json_error(['message'=>esc_html__('Something went wrong!','sina-ext')]);}}private function verify_ajax_request($capability='manage_options'){if(empty($_POST)){wp_send_json_error(['message'=>esc_html__('Something went wrong!','sina-ext')]);return false;}$nonce=isset($_POST['nonce'])?sanitize_text_field(wp_unslash($_POST['nonce'])):'';if(!wp_verify_nonce($nonce,'sina_ext_tmp_nonce')){wp_send_json_error(['message'=>esc_html__('Nonce Verification Failed!','sina-ext')]);return false;}if(!(current_user_can($capability)||current_user_can('edit_others_posts'))){wp_send_json_error(['message'=>esc_html__('You are unauthorized to adding template!','sina-ext')]);return false;}return true;}public function save_template(){if(!$this->verify_ajax_request()){return;}$title=!empty($_POST['title'])?sanitize_text_field(wp_unslash($_POST['title'])):'';$tmpid=!empty($_POST['tmpId'])?absint(wp_unslash($_POST['tmpId'])):0;$tmpType=!empty($_POST['tmpType'])?sanitize_text_field(wp_unslash($_POST['tmpType'])):'single';$tmplocation=!empty($_POST['tmpDisplay'])?sanitize_text_field(wp_unslash($_POST['tmpDisplay'])):'';$specificsDisplay='';if(!empty($_POST['specificsDisplay'])){$sp_decoded=json_decode(wp_unslash($_POST['specificsDisplay']),true);if(is_array($sp_decoded)){$specificsDisplay=wp_json_encode(array_map('absint',$sp_decoded));}}$data=['title'=>$title,'id'=>$tmpid,'tmptype'=>$tmpType,'tmplocation'=>$tmplocation,'tmpSpLocation'=>$specificsDisplay,];if($tmpid){$this->update_template($data);}else{$this->create_template($data);}}public function update_template($data){$existing=get_post($data['id']);if(!$existing||$existing->post_type!==self::POST_TYPE){wp_send_json_error(['message'=>esc_html__('Template not found.','sina-ext')]);return;}wp_update_post(['ID'=>$data['id'],'post_title'=>$data['title'],]);update_post_meta($data['id'],self::POST_TYPE_META.'_type',$data['tmptype']);update_post_meta($data['id'],self::POST_TYPE_META.'_location',$data['tmplocation']);if('popup'===$data['tmptype']){update_post_meta($data['id'],'_elementor_template_type','sina_popup');}elseif('sidebar'===$data['tmptype']){update_post_meta($data['id'],'_elementor_template_type','sina_sidebar');}else{delete_post_meta($data['id'],'_elementor_template_type');}if(in_array($data['tmptype'],['header','footer','popup','sidebar'])){update_post_meta($data['id'],self::POST_TYPE_META.'_splocation',$data['tmpSpLocation']);}else{delete_post_meta($data['id'],self::POST_TYPE_META.'_splocation');}wp_send_json_success(['message'=>esc_html__('Template has been updated','sina-ext'),'id'=>$data['id'],]);}public function get_template_by_id(){if(!$this->verify_ajax_request()){return;}$tmpid=!empty($_POST['tmpId'])?sanitize_text_field(wp_unslash($_POST['tmpId'])):0;if(!$tmpid){wp_send_json_error(['message'=>esc_html__('Invalid template ID.','sina-ext')]);return;}$postdata=get_post($tmpid);if(!$postdata||$postdata->post_type!==self::POST_TYPE){wp_send_json_error(['message'=>esc_html__('Template not found.','sina-ext')]);return;}$tmpType=get_post_meta($tmpid,self::POST_TYPE_META.'_type',true)?:'single';$tmpLocation=get_post_meta($tmpid,self::POST_TYPE_META.'_location',true)?:'';$specificsDisplay=get_post_meta($tmpid,self::POST_TYPE_META.'_splocation',true)?:'';$spLocations=[];if(!empty($specificsDisplay)){foreach(json_decode($specificsDisplay)as $item){$sppost=get_post(intval($item));if($sppost){$spLocations[$item]=$sppost->post_title;}}}wp_send_json_success(['tmpTitle'=>$postdata->post_title,'tmpType'=>$tmpType,'tmpLocation'=>$tmpLocation,'tmpSpLocation'=>$spLocations,]);}public function query_filter(\WP_Query $query){if(!is_admin()||!empty($query->query_vars['meta_key'])||self::POST_TYPE!==$query->get('post_type')){return;}$template_type=isset($_GET['template_type'])?sanitize_key($_GET['template_type']):'';if(''!==$template_type&&'all'!==$template_type){$query->query_vars['meta_key']=self::POST_TYPE_META.'_type';$query->query_vars['meta_value']=$template_type;$query->query_vars['meta_compare']='=';}}public function get_posts_by_query(){if(!$this->verify_ajax_request()){return;}$search_string=isset($_POST['q'])?sanitize_text_field(wp_unslash($_POST['q'])):'';$post_types=get_post_types(['public'=>true,'_builtin'=>false],'names','and');$result=[];unset($post_types[self::POST_TYPE]);$post_types['Posts']='post';$post_types['Pages']='page';foreach($post_types as $key=>$post_type){$data=[];add_filter('posts_search',[$this,'search_only_titles'],10,2);$query=new \WP_Query(['s'=>$search_string,'post_type'=>$post_type,'posts_per_page'=>100,]);remove_filter('posts_search',[$this,'search_only_titles'],10);if($query->have_posts()){while($query->have_posts()){$query->the_post();$title=get_the_title();$title.=(0!=$query->post->post_parent)?' ('.get_the_title($query->post->post_parent).')':'';$data[]=['id'=>get_the_id(),'text'=>$title,];}}if(!empty($data)){$result[]=['text'=>$key,'children'=>$data,];}}wp_reset_postdata();wp_send_json($result);}public function search_only_titles($